import{z as A,x as p,o as r,c as d,q as E,j as o,D as e,d as n,s as l,S as i,b as t}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"意向锁与粒度","description":"","frontmatter":{"title":"意向锁与粒度","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/intention-locks.md","filePath":"cs/intention-locks.md","lastUpdated":1791063341000}'),B={name:"cs/intention-locks.md"};function m(h,a,c,I,u,C){const s=p("Mermaid");return r(),d("div",null,[a[2]||(a[2]=E('<h1 id="意向锁与粒度" tabindex="-1">意向锁与粒度 <a class="header-anchor" href="#意向锁与粒度" aria-label="Permalink to &quot;意向锁与粒度&quot;">​</a></h1><div class="epigraph"><p>要锁一行，先在表上挂意向：别人想锁整表时能看见冲突，而不必枚举所有行锁。</p><footer>—— 据 Gray, Lorie, Putzolu and Traiger 多粒度锁，1975；Gray and Reuter；Ramakrishnan and Gehrke</footer></div><p><a href="/cs/ssi">上一课</a>在行版本上追踪冲突。本课回到悲观锁的<strong>粒度</strong>：行、页、表。主干 2PL 常默实行锁。缺口是多粒度：若只行锁，全表扫描的互斥要百万把锁；若只表锁，并发为零。意向锁（IS/IX）在祖先上做标记。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>层次：数据库–表–页–行。事务要 X 锁行：先 IX 表、IX 页，再 X 行。另一事务要 X 表：与 IX 冲突，等待，不必看每一行。缺口是<strong>相容矩阵</strong>：IS 与 IX 相容，X 与一切意向在同对象上冲突等。锁升级：行锁太多则升表锁，减少内存，增加冲突。</p><p><span class="marginnote">术语翻译：IS＝「我打算在下面加共享锁」，IX＝「我打算在下面加排他锁」。它们自己不锁任何数据，只是挂在祖先（表、页）上的告示牌，让粗粒度请求不必枚举全部细粒度锁。</span></p><p>与 latch：latch 仍短、在页结构上；意向锁是事务锁，可持有到提交（严格 2PL）。</p><p><span class="marginnote">Gray et al. IBM 多粒度。SQL Server、DB2、InnoDB 都有表/行意向。Postgres 行锁+表级 ACCESS SHARE 等是另一套名字，机制同族。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>加锁自上而下，释放自下而上（或提交一次性），避免死锁协议破环。查询计划决定粒度：全表更新应直接表锁，不要先锁每一行再升级。优化器与锁：顺序扫描仍可能行锁，HOT 更新同页。</p><p>覆盖：意向不替代行上的 X；它是祖先上的警告灯。</p><p><span class="marginnote">直觉类比：意向锁像楼层门口的「楼内有人」指示灯——你想给整层断电（表锁），不必挨个房间查看，瞄一眼门口的灯就知道里面有没有人；每个进房间的人（行锁）进门时先按下这盏灯。</span></p>',12)),(r(),o(i,null,{default:e(()=>[l(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20TAB%5B%22%E8%A1%A8%20IX%22%5D%20--%3E%20PG%5B%22%E9%A1%B5%20IX%22%5D%0A%20%20PG%20--%3E%20ROW%5B%22%E8%A1%8C%20X%22%5D%0A%20%20TAB2%5B%22%E8%A1%A8%20X%22%5D%20--%3E%20WAIT%5B%22%E4%B8%8E%20IX%20%E5%86%B2%E7%AA%81%E7%AD%89%E5%BE%85%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[n("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"死锁：两事务对表与行反序仍可环，wait-for 下一课。SSI 的 SIREAD 也是一种范围意向。分区表：锁可停在分区级。",-1)),a[5]||(a[5]=t("p",null,"授予判定怎么做到「不枚举行锁」：只看同对象上的已有标记。",-1)),(r(),o(i,null,{default:e(()=>[l(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E6%96%B0%E8%AF%B7%E6%B1%82%EF%BC%9AX%20%E9%94%81%E6%95%B4%E8%A1%A8%22%5D%20--%3E%20C%7B%22%E8%A1%A8%E4%B8%8A%E5%B7%B2%E6%9C%89%20IS%2FIX%3F%22%7D%0A%20%20C%20--%3E%7C%22%E6%97%A0%22%7C%20G%5B%22%E7%9B%B4%E6%8E%A5%E6%8E%88%E4%BA%88%E8%A1%A8%20X%22%5D%0A%20%20C%20--%3E%7C%22%E6%9C%89%22%7C%20W%5B%22%E7%AD%89%E5%BE%85%E5%85%A8%E9%83%A8%E6%84%8F%E5%90%91%E9%87%8A%E6%94%BE%22%5D%0A%20%20REQ2%5B%22%E6%96%B0%E8%AF%B7%E6%B1%82%EF%BC%9AX%20%E9%94%81%E6%9F%90%E8%A1%8C%22%5D%20--%3E%20I%5B%22%E5%85%88%E7%BB%99%E8%A1%A8%E6%8C%82%20IX%EF%BC%8C%E5%86%8D%E9%94%81%E8%AF%A5%E8%A1%8C%22%5D%0A%20%20I%20--%3E%20G2%5B%22%E6%95%B4%E8%A1%A8%E8%AF%B7%E6%B1%82%E5%B0%86%E6%9D%A5%E7%9C%8B%E5%88%B0%20IX%20%E5%8D%B3%E7%9F%A5%E6%9C%89%E4%BA%BA%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=E('<p><span class="marginnote">数字实例：一张 100 万行的表，没有意向锁时，互斥地全表更新得逐行比对 100 万把锁；有了表级 IX 标记，查一次表就够。反过来若总是用表锁，100 个各读一行的事务也只能完全排队——两端都不划算。</span></p><p>内存：锁表项数是容量。升级阈值是调参。计划回归：突然表锁把并发打穿，像优化器选了全表更新路径。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 next-key。也不把文件锁当意向。分布式锁粒度更粗，后课。</p><p>后课默认：行锁路径必先意向祖先。间隙锁与谓词锁：防幻象的范围，不只点行。</p><p>没有意向，表级互斥只能靠「锁所有行」或「总是表锁」两端。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>多粒度用 IS/IX 标记祖先，使表锁与行锁可检测冲突。</li><li>加锁自上而下；升级是容量阀门。</li><li>间隙锁与谓词锁下一课。</li><li>出处：Gray et al. 1975；Gray and Reuter；Ramakrishnan and Gehrke。</li></ul>',8))])}const X=A(B,[["render",m]]);export{f as __pageData,X as default};
